type Counter struct {
    mu sync.Mutex
    n  int
}

func (c *Counter) Value() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.n
}

func (c *Counter) Incr() {
    c.mu.Lock()
    defer c.mu.Unlock()
    if c.Value() < 100 {
        c.n++
    }
}

