solution.code:
func (s *Service) GetUser(ctx context.Context, id string) (User, error) {
    s.mu.Lock()
    u, ok := s.cache[id]
    s.mu.Unlock()
    if ok {
        return u, nil
    }
    u, err := s.db.LoadUser(ctx, id) // вне lock
    if err != nil {
        return User{}, err
    }
    s.mu.Lock()
    s.cache[id] = u
    s.mu.Unlock()
    return u, nil
}
